mapper.select:
SELECT id, user_id AS userId, category, difficulty, status, start_time AS startTime, end_time AS endTime, create_time AS createTime
FROM interview_session
WHERE id = #{id}

mapper.update:
UPDATE interview_session

SET
status = #{status},
end_time = #{endTime}

WHERE id = #{id}
  AND status = 'IN_PROGRESS'
